/// A malformed entry (docs/spec.md §3.14.2).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DecodeError(pub &'static str);

mod codec {
    use super::DecodeError;

    pub fn nat(v: i128, out: &mut Vec<u8>) {
        // A Nat is never negative; 0 stands in for what cannot happen.
        let mut x = u128::try_from(v).unwrap_or(0);
        loop {
            let b = u8::try_from(x & 0x7F).unwrap_or(0);
            x >>= 7;
            if x == 0 {
                out.push(b);
                return;
            }
            out.push(b | 0x80);
        }
    }
    pub fn int(v: i128, out: &mut Vec<u8>) {
        // zigzag: 0, -1, 1, -2, ... as 0, 1, 2, 3, ...
        let z = if v >= 0 { u128::try_from(v).unwrap_or(0) << 1 } else { (v.unsigned_abs().saturating_sub(1) << 1) | 1 };
        let mut x = z;
        loop {
            let b = u8::try_from(x & 0x7F).unwrap_or(0);
            x >>= 7;
            if x == 0 {
                out.push(b);
                return;
            }
            out.push(b | 0x80);
        }
    }
    pub fn boolean(v: bool, out: &mut Vec<u8>) {
        out.push(u8::from(v));
    }
    pub fn len(n: usize, out: &mut Vec<u8>) {
        nat(i128::try_from(n).unwrap_or(0), out);
    }

    pub struct Rd<'a> {
        pub b: &'a [u8],
        pub p: usize,
    }

    impl Rd<'_> {
        pub fn byte(&mut self) -> Result<u8, DecodeError> {
            let v = *self.b.get(self.p).ok_or(DecodeError("end of entry"))?;
            self.p = self.p.saturating_add(1);
            Ok(v)
        }
        fn raw(&mut self) -> Result<u128, DecodeError> {
            let mut x: u128 = 0;
            let mut sh: u32 = 0;
            loop {
                let b = self.byte()?;
                if sh > 126 {
                    return Err(DecodeError("a number too long"));
                }
                x |= u128::from(b & 0x7F) << sh;
                sh = sh.saturating_add(7);
                if b & 0x80 == 0 {
                    return Ok(x);
                }
            }
        }
        pub fn nat(&mut self) -> Result<i128, DecodeError> {
            i128::try_from(self.raw()?).map_err(|_| DecodeError("a number out of range"))
        }
        pub fn int(&mut self) -> Result<i128, DecodeError> {
            let z = self.raw()?;
            let m = i128::try_from(z >> 1).map_err(|_| DecodeError("a number out of range"))?;
            Ok(if z & 1 == 0 { m } else { m.checked_neg().and_then(|x| x.checked_sub(1)).ok_or(DecodeError("a number out of range"))? })
        }
        pub fn boolean(&mut self) -> Result<bool, DecodeError> {
            match self.byte()? {
                0 => Ok(false),
                1 => Ok(true),
                _ => Err(DecodeError("a Bool")),
            }
        }
        pub fn len(&mut self) -> Result<usize, DecodeError> {
            usize::try_from(self.nat()?).map_err(|_| DecodeError("a length"))
        }
        pub fn done(&self) -> bool {
            self.p == self.b.len()
        }
    }
}

/// A value printed as mCRL2 prints it (for the tests that compare with mCRL2).
pub trait M2 {
    fn m2(&self, out: &mut String);
}

impl M2 for i128 {
    fn m2(&self, out: &mut String) {
        out.push_str(&self.to_string());
    }
}

impl M2 for bool {
    fn m2(&self, out: &mut String) {
        out.push_str(if *self { "true" } else { "false" });
    }
}

impl<X: M2> M2 for Vec<X> {
    fn m2(&self, out: &mut String) {
        out.push('[');
        for (k, x) in self.iter().enumerate() {
            if k > 0 {
                out.push_str(", ");
            }
            x.m2(out);
        }
        out.push(']');
    }
}

impl<X: M2> M2 for BTreeSet<X> {
    fn m2(&self, out: &mut String) {
        out.push('{');
        for (k, x) in self.iter().enumerate() {
            if k > 0 {
                out.push_str(", ");
            }
            x.m2(out);
        }
        out.push('}');
    }
}

#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Default, Copy)]
pub enum Phase {
    #[default]
    EDITING,
    SENDING,
    SENT,
    FAILED,
}

impl M2 for Phase {
    fn m2(&self, out: &mut String) {
        out.push_str(match self {
            Phase::EDITING => "EDITING",
            Phase::SENDING => "SENDING",
            Phase::SENT => "SENT",
            Phase::FAILED => "FAILED",
        });
    }
}

/// The configuration parameters of Core (§3.6.2).
#[derive(Debug, Clone)]
pub struct Config {
    pub limit: i128,
}

/// A state of Core: one field per parameter.
#[derive(Debug, Clone)]
pub struct S {
    pub limit: i128,
    pub phase: Phase,
    pub valid: bool,
    pub tries: i128,
    pub queued: bool,
}

fn initial(config: &Config) -> Result<S, StepError> {
    Ok(S {
        limit: rt::fit(config.limit.clone(), 0, 4294967295, "limit")?,
        phase: Phase::EDITING,
        valid: false,
        tries: rt::fit(0i128, 0, 4294967295, "tries")?,
        queued: false,
    })
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Event {
    Edit(bool),
    Failed,
    Submit,
    Succeeded,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Action {
    Send(i128),
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Entry {
    Event(Event),
    Action(Action),
}

// c_edit
fn match0(s: &S, a0: &bool) -> Result<Option<(bool, )>, StepError> {
    let v_v = a0.clone();
    if !(((s.phase.clone() == Phase::EDITING) || (s.phase.clone() == Phase::FAILED))) {
        return Ok(None);
    }
    Ok(Some((v_v, )))
}

fn fire0(s: &mut S, env: (bool, )) -> Result<(), StepError> {
    let (v_v, ) = env;
    let n_phase = Phase::EDITING;
    let n_valid = v_v.clone();
    s.phase = n_phase;
    s.valid = n_valid;
    Ok(())
}

// c_submit
fn match1(s: &S) -> Result<Option<()>, StepError> {
    if !((((s.phase.clone() == Phase::EDITING) || (s.phase.clone() == Phase::FAILED)) && (s.valid.clone() && (s.tries.clone() < s.limit.clone())))) {
        return Ok(None);
    }
    Ok(Some(()))
}

fn fire1(s: &mut S, env: ()) -> Result<(), StepError> {
    let () = env;
    let n_phase = Phase::SENDING;
    let n_queued = true;
    s.phase = n_phase;
    s.queued = n_queued;
    Ok(())
}

// c_succeeded
fn match2(s: &S) -> Result<Option<()>, StepError> {
    if !(((s.phase.clone() == Phase::SENDING) && (!s.queued.clone()))) {
        return Ok(None);
    }
    Ok(Some(()))
}

fn fire2(s: &mut S, env: ()) -> Result<(), StepError> {
    let () = env;
    let n_phase = Phase::SENT;
    s.phase = n_phase;
    Ok(())
}

// c_failed
fn match3(s: &S) -> Result<Option<()>, StepError> {
    if !(((s.phase.clone() == Phase::SENDING) && (!s.queued.clone()))) {
        return Ok(None);
    }
    Ok(Some(()))
}

fn fire3(s: &mut S, env: ()) -> Result<(), StepError> {
    let () = env;
    let n_phase = Phase::FAILED;
    let n_tries = rt::add(s.tries.clone(), 1i128)?;
    s.phase = n_phase;
    s.tries = rt::fit(n_tries, 0, 4294967295, "tries")?;
    Ok(())
}

// c_send
fn match4(s: &S, a0: &i128) -> Result<Option<()>, StepError> {
    if *a0 != rt::add(s.tries.clone(), 1i128)? {
        return Ok(None);
    }
    if !(s.queued.clone()) {
        return Ok(None);
    }
    Ok(Some(()))
}

fn fire4(s: &mut S, env: ()) -> Result<(), StepError> {
    let () = env;
    let n_queued = false;
    s.queued = n_queued;
    Ok(())
}

/// Checks the action record against the unrefined Core (docs/spec.md §3.8.9).
#[derive(Debug)]
pub struct Acceptor {
    s: S,
}

impl Acceptor {
    pub fn new(config: Config) -> Result<Acceptor, StepError> {
        Ok(Acceptor { s: initial(&config)? })
    }

    /// The state, for tests.
    pub fn state(&self) -> &S {
        &self.s
    }

    /// The state, for tests that start from another initial state.
    #[doc(hidden)]
    pub fn state_mut(&mut self) -> &mut S {
        &mut self.s
    }

    pub fn accept(&mut self, entry: &Entry) -> Result<(), Reject> {
        match entry {
            Entry::Action(Action::Send(a0)) => {
                let e4 = match4(&self.s, a0).map_err(Reject::Step)?;
                let found = [e4.is_some()].iter().filter(|x| **x).count();
                if found > 1 {
                    return Err(Reject::Ambiguous);
                }
                if let Some(env) = e4 {
                    return fire4(&mut self.s, env).map_err(Reject::Step);
                }
                Err(Reject::Rejected)
            }
            Entry::Event(Event::Edit(a0)) => {
                let e0 = match0(&self.s, a0).map_err(Reject::Step)?;
                let found = [e0.is_some()].iter().filter(|x| **x).count();
                if found > 1 {
                    return Err(Reject::Ambiguous);
                }
                if let Some(env) = e0 {
                    return fire0(&mut self.s, env).map_err(Reject::Step);
                }
                Err(Reject::Rejected)
            }
            Entry::Event(Event::Failed) => {
                let e3 = match3(&self.s).map_err(Reject::Step)?;
                let found = [e3.is_some()].iter().filter(|x| **x).count();
                if found > 1 {
                    return Err(Reject::Ambiguous);
                }
                if let Some(env) = e3 {
                    return fire3(&mut self.s, env).map_err(Reject::Step);
                }
                Err(Reject::Rejected)
            }
            Entry::Event(Event::Submit) => {
                let e1 = match1(&self.s).map_err(Reject::Step)?;
                let found = [e1.is_some()].iter().filter(|x| **x).count();
                if found > 1 {
                    return Err(Reject::Ambiguous);
                }
                if let Some(env) = e1 {
                    return fire1(&mut self.s, env).map_err(Reject::Step);
                }
                Err(Reject::Rejected)
            }
            Entry::Event(Event::Succeeded) => {
                let e2 = match2(&self.s).map_err(Reject::Step)?;
                let found = [e2.is_some()].iter().filter(|x| **x).count();
                if found > 1 {
                    return Err(Reject::Ambiguous);
                }
                if let Some(env) = e2 {
                    return fire2(&mut self.s, env).map_err(Reject::Step);
                }
                Err(Reject::Rejected)
            }
        }
    }
}

fn enc_Phase(v: &Phase, out: &mut Vec<u8>) {
    codec::nat(match v {
        Phase::EDITING => 0,
        Phase::SENDING => 1,
        Phase::SENT => 2,
        Phase::FAILED => 3,
    }, out);
}

fn dec_Phase(r: &mut codec::Rd<'_>) -> Result<Phase, DecodeError> {
    match r.nat()? {
        0 => Ok(Phase::EDITING),
        1 => Ok(Phase::SENDING),
        2 => Ok(Phase::SENT),
        3 => Ok(Phase::FAILED),
        _ => Err(DecodeError("a constructor index")),
    }
}

/// The bytes of an entry (docs/spec.md §3.8.10).
pub fn encode(entry: &Entry, out: &mut Vec<u8>) {
    match entry {
        Entry::Event(Event::Edit(a0)) => {
            out.push(0);
            codec::nat(0, out);
            codec::boolean(*(a0), out);
        }
        Entry::Event(Event::Failed) => {
            out.push(0);
            codec::nat(1, out);
        }
        Entry::Event(Event::Submit) => {
            out.push(0);
            codec::nat(2, out);
        }
        Entry::Event(Event::Succeeded) => {
            out.push(0);
            codec::nat(3, out);
        }
        Entry::Action(Action::Send(a0)) => {
            out.push(1);
            codec::nat(0, out);
            codec::nat(*(a0), out);
        }
    }
}

/// The entry of some bytes (§3.8.10).
pub fn decode(bytes: &[u8]) -> Result<Entry, DecodeError> {
    let mut r = codec::Rd { b: bytes, p: 0 };
    let r = &mut r;
    let side = r.byte()?;
    let code = r.nat()?;
    let e = match (side, code) {
        (0, 0) => Entry::Event(Event::Edit(r.boolean()?)),
        (0, 1) => Entry::Event(Event::Failed),
        (0, 2) => Entry::Event(Event::Submit),
        (0, 3) => Entry::Event(Event::Succeeded),
        (1, 0) => Entry::Action(Action::Send(r.nat()?)),
        _ => return Err(DecodeError("a label")),
    };
    if !r.done() {
        return Err(DecodeError("trailing bytes"));
    }
    Ok(e)
}

/// The indexes refreshed at the ids the last summand wrote (docs/spec.md §3.8.3).
fn refresh(s: &mut S) -> Result<(), StepError> {
    Ok(())
}

fn stepper_init(s: &mut S) -> Result<(), StepError> {
    Ok(())
}

// c_edit
fn match_s0(s: &S, a0: &bool) -> Result<Option<(bool, )>, StepError> {
    let v_v = a0.clone();
    if !(((s.phase.clone() == Phase::EDITING) || (s.phase.clone() == Phase::FAILED))) {
        return Ok(None);
    }
    Ok(Some((v_v, )))
}

fn fire_s0(s: &mut S, env: (bool, )) -> Result<(), StepError> {
    let (v_v, ) = env;
    let n_phase = Phase::EDITING;
    let n_valid = v_v.clone();
    s.phase = n_phase;
    s.valid = n_valid;
    Ok(())
}

// c_submit
fn match_s1(s: &S) -> Result<Option<()>, StepError> {
    if !((((s.phase.clone() == Phase::EDITING) || (s.phase.clone() == Phase::FAILED)) && (s.valid.clone() && (s.tries.clone() < s.limit.clone())))) {
        return Ok(None);
    }
    Ok(Some(()))
}

fn fire_s1(s: &mut S, env: ()) -> Result<(), StepError> {
    let () = env;
    let n_phase = Phase::SENDING;
    let n_queued = true;
    s.phase = n_phase;
    s.queued = n_queued;
    Ok(())
}

// c_succeeded
fn match_s2(s: &S) -> Result<Option<()>, StepError> {
    if !(((s.phase.clone() == Phase::SENDING) && (!s.queued.clone()))) {
        return Ok(None);
    }
    Ok(Some(()))
}

fn fire_s2(s: &mut S, env: ()) -> Result<(), StepError> {
    let () = env;
    let n_phase = Phase::SENT;
    s.phase = n_phase;
    Ok(())
}

// c_failed
fn match_s3(s: &S) -> Result<Option<()>, StepError> {
    if !(((s.phase.clone() == Phase::SENDING) && (!s.queued.clone()))) {
        return Ok(None);
    }
    Ok(Some(()))
}

fn fire_s3(s: &mut S, env: ()) -> Result<(), StepError> {
    let () = env;
    let n_phase = Phase::FAILED;
    let n_tries = rt::add(s.tries.clone(), 1i128)?;
    s.phase = n_phase;
    s.tries = rt::fit(n_tries, 0, 4294967295, "tries")?;
    Ok(())
}

// c_send
fn out0(s: &mut S, out: &mut Vec<Action>) -> Result<bool, StepError> {
    if !(s.queued.clone()) {
        return Ok(false);
    }
    let act = Action::Send(rt::add(s.tries.clone(), 1i128)?);
    let n_queued = false;
    s.queued = n_queued;
    out.push(act);
    Ok(true)
}

const OUTS: [fn(&mut S, &mut Vec<Action>) -> Result<bool, StepError>; 1] = [out0];

/// The output loop (docs/spec.md §3.8.3): the first enabled output in policy
/// order, until none is.
fn run_loop(s: &mut S, out: &mut Vec<Action>) -> Result<(), StepError> {
    let mut n: u32 = 0;
    loop {
        let mut fired = false;
        for f in OUTS {
            if f(s, out)? {
                fired = true;
                break;
            }
        }
        if !fired {
            return Ok(());
        }
        refresh(s)?;
        n = n.saturating_add(1);
        if n >= 1 << 24 {
            return Err(StepError::StepLimit);
        }
    }
}

fn state_bytes(s: &S, out: &mut Vec<u8>) {
    codec::nat(*(&s.limit), out);
    enc_Phase(&s.phase, out);
    codec::boolean(*(&s.valid), out);
    codec::nat(*(&s.tries), out);
    codec::boolean(*(&s.queued), out);
}

/// The stepper of the refined Core (docs/spec.md §3.8.1, §3.8.2, §3.11.2).
#[derive(Debug, Clone)]
pub struct State {
    s: S,
}

impl State {
    pub fn new(config: Config, out: &mut Vec<Action>) -> Result<State, StepError> {
        State::new_with(config, out, |_| {})
    }

    /// The constructor with the initial state changed first, for tests that start
    /// from another initial state.
    #[doc(hidden)]
    pub fn new_with(config: Config, out: &mut Vec<Action>, f: impl FnOnce(&mut S)) -> Result<State, StepError> {
        let mut s = initial(&config)?;
        f(&mut s);
        stepper_init(&mut s)?;
        run_loop(&mut s, out)?;
        Ok(State { s })
    }

    pub fn step(&mut self, event: &Event, out: &mut Vec<Action>) -> Result<(), StepError> {
        let s = &mut self.s;
        match event {
            Event::Edit(a0) => {
                if let Some(env) = match_s0(s, a0)? {
                    fire_s0(s, env)?;
                } else {
                    return Err(StepError::Refused(event.clone()));
                }
            }
            Event::Failed => {
                if let Some(env) = match_s3(s)? {
                    fire_s3(s, env)?;
                } else {
                    return Err(StepError::Refused(event.clone()));
                }
            }
            Event::Submit => {
                if let Some(env) = match_s1(s)? {
                    fire_s1(s, env)?;
                } else {
                    return Err(StepError::Refused(event.clone()));
                }
            }
            Event::Succeeded => {
                if let Some(env) = match_s2(s)? {
                    fire_s2(s, env)?;
                } else {
                    return Err(StepError::Refused(event.clone()));
                }
            }
        }
        refresh(s)?;
        run_loop(s, out)
    }

    /// An estimate of the memory the state holds (§3.13.4).
    pub fn bytes(&self) -> usize {
        let mut b = Vec::new();
        state_bytes(&self.s, &mut b);
        b.len()
    }

    /// Every parameter's value, encoded as entries are (for comparing the backends).
    pub fn state_bytes(&self) -> Vec<u8> {
        let mut b = Vec::new();
        state_bytes(&self.s, &mut b);
        b
    }

    /// The state, for tests.
    pub fn state(&self) -> &S {
        &self.s
    }

    /// The members of an index in its order, for tests.
    pub fn index(&self, name: &str) -> Option<Vec<u32>> {
        match name {
            _ => None,
        }
    }
}

